    onKeyDown,
    open = false,
    TooltipClasses,
    tooltipOpen: tooltipOpenProp = false,
    tooltipPlacement = 'left',
    tooltipTitle,
    ...other
  } = props;

  const [tooltipOpen, setTooltipOpen] = React.useState(tooltipOpenProp);
  const timeout = React.useRef();
  const [prevPropOpen, setPreviousOpen] = React.useState(null);

  // getDerivedStateFromProps alternate
  if (!open && tooltipOpen) {
    setTooltipOpen(false);
    setPreviousOpen(open);
  }

  React.useEffect(() => {
    if (!tooltipOpenProp || prevPropOpen === open) {
      return undefined;
    }

    if (!tooltipOpen) {
      timeout.current = setTimeout(() => setTooltipOpen(true), delay + 100);
      return () => {
        clearTimeout(timeout.current);
      };
    }

    return undefined;
  });

  const handleTooltipClose = () => {
    if (tooltipOpenProp) return;
    setTooltipOpen(false);
  };

  const handleTooltipOpen = () => {
    if (tooltipOpenProp) return;
    setTooltipOpen(true);
  };

  let clickProp = { onClick };
  if (typeof document !== 'undefined' && 'ontouchstart' in document.documentElement) {
    let startTime;
    clickProp = {
      onTouchStart: () => {
        startTime = new Date();
      },
      onTouchEnd: event => {
        // only perform action if the touch is a tap, i.e. not long press
        if (new Date() - startTime < 500) {
          onClick(event);
        }
      },
    };
  }

  return (
    <Tooltip
      id={id}
      ref={ref}
      title={tooltipTitle}
      placement={tooltipPlacement}
      onClose={handleTooltipClose}
      onOpen={handleTooltipOpen}
      open={open && tooltipOpen}
      classes={TooltipClasses}
      {...other}
    >
      <Fab
        size="small"
        className={clsx(className, classes.button, !open && classes.buttonClosed)}
        style={{ transitionDelay: `${delay}ms` }}
        tabIndex={-1}
        role="menuitem"
        onKeyDown={onKeyDown}
        {...ButtonProps}
        {...clickProp}
      >
        {icon}
      </Fab>
    </Tooltip>
  );
});

